-- aar/w3/aar_row_579_draft1.sql. DRAFT 1 by W3 (session_01H1X3ANsGiMnhnbkfphocmo) for the coordinator (seat 36). NOT RUN by W3.
-- One ask_aar_snapshots row for ASK 579 and its ask_aar_builders row.
-- Every value is from the Wall post named in its source (read by W3 19:44 to 19:49 CST 2026-11-24: 11099, 11104, 11114, 11736, 11739, 11744, 11756, 11757, 11759, 11762, 11764, 11775, 11778, 11779, 11781, the first 700 to 1,500 characters of each), from W4's files under /mnt/project-files/ask579/w4/ (md5sum and sha256sum by W3; notes579.md and write579_run.txt read; the PASS lines of out_t579.txt counted), from the plan rev 2 (section 1 read), from md_notes_rulings row 539, from audit rows 41763, 41783, 41819, 41828, 41852 (titles and first 420 characters read), or from W4's thread note to W3 (the two write cards).
-- NOT READ by W3: W4's cards themselves; W1's grade and readback files in git (the Wall posts name them); n8n; the tails of the Wall posts beyond the characters named above.
-- HASH KINDS: every md5 here is an md5. The sha256 prefixes of the two targets are given beside them.
-- W3 is planner and wrote the prototype; ask_aar_builders names W4 and W3. The grades are W1's.
-- objective_met is 'in part': written and read back MATCH; no run since the write; the try-node re-call path shown by nothing; manual entry not written.
-- After the insert: SELECT * FROM ask_aar_snapshots_check(); SELECT * FROM ask_aar_grades_check();
-- The session line below must be the coordinator's own session; written_by is read from it.
BEGIN;
SET LOCAL truth.session_id = '<COORDINATOR SESSION, registered to seat 36>';
WITH s AS (
INSERT INTO ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, owner_seat, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources)
VALUES (579, '2', $t$ASK 579: the re-call reply blocks of nine Extract nodes are served from the Shared Library$t$,
  $t$Nine engine nodes each hold one large block that reads a debater's re-call reply: the `__O423` statement in C2B, D3B and C3B Extract, and the call inside `try{__X2=(()=>{...})()[0].json;}` in C4G, C3G, C1B, D2B, D4B and C4B Extract. The nine texts share most of their lines. Store each line once in the Shared Library and let each node rebuild its own text, byte for byte. Expected effect: 44,229 characters less stored while the child keeps its library copy, 114,298 once ASK 578 removes that copy (measured today, section 5); one place to edit a line the nine nodes share. No behaviour changes: no prompt text, no reasoning setting, no check and no output. (plan rev 2, section 1 OBJECTIVE, fairjudge/w3/a579/ASK579_plan_rev2.md md5 922b1a04)$t$,
  'in part',
  $t$Written by W4 at 17:43 CST 2026-11-24 on the operator's press and read back MATCH by W1 (Wall 11775, 11781; audit 41763). Engine 20db58ee to 3afa1c1f: nine Extract nodes and the Shared Library changed; child 74353c40 to cd97165c: the Shared Library only; library a3c1e42f5b0ebda6, 3,852 lines, map ed7212a3189a4565. IN PART because the plan asks for the manual entry and two clean live runs, and neither exists, and one path is shown by no run. SHOWN: t579.js on the base, 99 checks, ALL PASS (W4, and W1's own rebuild, byte-equal targets); C6: each of the nine nodes, run offline on the stored inputs of run 42071, gives the same output as before, 9 of 9, on the live code, on the target and on the fetch-back; standing set 31 PASS, 0 FAIL; pair Library Check PASSES. NOT SHOWN: a re-call through one of the six try nodes (in run 42071 a re-call ran in C2B and C3B Extract only; Wall 11756). Measured: the nine nodes go from 226,060 to 41,693 characters and each library gains 70,069; the net saving was 44,229 with the child's copy and is 114,298 since ASK 578 removed that copy (19:08 CST, audit 41852). Stated cost (W1's plan note N1): the new entries reuse 37 existing library lines that 54 existing MAP entries serve too, so a later edit of one of those lines changes the nine nodes as well. The write card of 16:35 CST was answered "Wait for the 611 run"; the write followed run 42373 on a second card, and that run was later found NOT clean for ASK 611 (Wall 11779; W1's caution in Wall 11781). ASK 579 neither caused nor fixed that defect (W4, Wall 11778). Run 42373 ran on engine 20db58ee, before this write, and does not exercise it.$t$,
  '11099, 11104, 11114, 11736, 11739, 11744, 11756, 11757, 11759, 11762, 11764, 11775, 11778, 11779, 11781',
  current_setting('truth.session_id'), NULL,
  to_jsonb($t$(1) W3's thread, 18:37 CST 2026-11-23: he pressed "Approve for build" on the card "Approve ASK 579 for build: nine layer blocks stored once in the library?" (Wall 11114). (2) W3's thread, 14:04 CST 2026-11-24, verbatim: "Let's take care of the library consolidation with the rest of these updates we're going to do for the lab improvements." (md_notes_rulings row 539; not a write approval). (3) W4's thread, 16:25 CST 2026-11-24: he pressed yes to a read of run 42071 limited to the nine Extract nodes and the nodes they name (Wall 11756; card id and wording not read by W3). (4) W4's card "Write ASK 579 now, or wait for the ASK 611 proving run?", posted 16:35 CST 2026-11-24: he pressed "Wait for the 611 run" at 16:40 CST (Wall 11764; W4's thread note to W3). (5) W4's card "Write ASK 579 to the live engine and child now?", posted 17:43 CST 2026-11-24: he pressed "Write it" at 17:43 CST (W4's thread note to W3; Wall 11775; audit 41763). W3 did not read cards (3) to (5).$t$::text),
  $j${"answer": "Write it", "question": "Write ASK 579 to the live engine and child now?", "thread": "W4", "card_id": "cmsg_017ZQamDMHrS6fqMHnQDVo58Cs1fQzFtikmw9FdePE5GwB", "press_time": "17:43 CST 2026-11-24", "options": "Write it / Hold", "source": "W4's thread note to W3, about 19:31 CST 2026-11-24 (card ids, wordings, options and press times); Wall 11775; audit 41763. Not read by W3.", "earlier_write_card": {"thread": "W4", "card_id": "cmsg_017ZQamDMHrS6fqMHnQDVo583tL4VbU8KB49xWF5bTnfFq", "question": "Write ASK 579 now, or wait for the ASK 611 proving run?", "options": "Wait for the 611 run / Write it now / Hold", "answer": "Wait for the 611 run", "posted": "16:35 CST 2026-11-24", "press_time": "16:40 CST 2026-11-24", "source": "W4's thread note to W3; Wall 11764"}, "build_card": {"thread": "W3", "question": "Approve ASK 579 for build: nine layer blocks stored once in the library?", "answer": "Approve for build", "press_time": "18:37 CST 2026-11-23", "source": "Wall 11114 (W3)"}, "read_card": {"thread": "W4", "what": "a read of execution 42071 limited to the nine Extract nodes and the nodes they name (39 nodes read)", "press_time": "16:25 CST 2026-11-24", "source": "Wall 11756. Card id and wording not read by W3."}}$j$::jsonb,
  'W3',
  $j${"md5": "922b1a04", "path": "fairjudge/w3/a579/ASK579_plan_rev2.md", "note": "plan rev 2 by W3, in the ASK FORM; graded PASS WITH N1 by W1 (Wall 11739). Draft 1 (ASK579_plan.md b1cba096, W1 PASS Wall 11104) carried the build approval of 2026-11-23; rev 2 changes the form, the base, how C6 is shown and the gates, not the change.", "commit": "50108126", "source": "md5sum by W3; Wall 11736, 11739, 11104"}$j$::jsonb,
  $j$[{"md5": "115b1db5", "sha256_prefix": "159b910b", "path": "ask579/w4/b2/target_engine_579.json", "note": "the engine target as written (write/target_engine_579.json is the same file)", "source": "md5sum and sha256sum by W3; Wall 11759, 11762"}, {"md5": "fe01ca77", "sha256_prefix": "ff355465", "path": "ask579/w4/b2/target_child_579.json", "note": "the child target as written (write/target_child_579.json is the same file)", "source": "md5sum and sha256sum by W3; Wall 11759, 11762"}, {"md5": "21150744", "path": "ask579/w4/b2/notes579.md", "note": "build notes of the re-cut; read whole by W3", "commit": "b28a7074", "source": "md5sum and read by W3; Wall 11759"}, {"md5": "be789169", "path": "ask579/w4/b2/t579.js", "note": "the build and test: W3's prototype, unchanged", "source": "md5sum by W3; notes579.md"}, {"md5": "ad55c232", "path": "ask579/w4/b2/out_t579.txt", "note": "test output: 99 lines beginning PASS (counted by W3), then ALL PASS (99 checks); write/t579_at_write.txt is byte-equal", "source": "md5sum, read and counted by W3"}, {"md5": "8bd90c58", "path": "ask579/w4/build/fixhdr579.js", "note": "resets the library header sha after t579.js; the md5 notes579.md names. The copy at ask579/w4/b2/fixhdr579.js now reads db5e7b08, because ASK 578 later added a mode to it (ask578/w4/b3/notes578.md, tool mode 3).", "source": "md5sum by W3 (both files); notes579.md; notes578.md"}, {"md5": "f869c51b", "path": "ask579/w4/c6/c6_579.cjs", "note": "the C6 replay; its inputs c6/in42071/rundata_42071.json 35c0b165", "commit": "f3f01bac", "source": "md5sum by W3; Wall 11756"}, {"md5": "902b568b", "path": "ask579/w4/b2/out_c6_579_target.txt", "note": "C6 on the target: 9 of 9 equal; byte-equal to c6/out_c6_579_live.txt (the live code) and to write/c6_at_write.txt (the fetch-back)", "source": "md5sum by W3 (three files, one md5)"}, {"md5": "e9d23edc", "path": "ask579/w4/write/write579.sh", "note": "the write script: run gate, rebuild byte-equal to the graded targets, live nodes equal the base, revert copies, standing set and pair check, PUT engine then child, fetch-back checks", "source": "md5sum by W3; notes579.md; Wall 11762"}, {"md5": "5439cd0d", "path": "ask579/w4/write/write579_run.txt", "note": "the write's own output: both PUTs http 200; engine 3afa1c1f-03ca-4297-8b7f-83ba8d6dd87c active, 423 nodes, params equal put, connections equal, changed the nine Extract nodes and Shared Library; child cd97165c-5818-4a68-8987-45d4057c91e1 active, 156 nodes, params equal put, connections equal, changed Shared Library; standing 31 PASS, 0 FAIL before and after; pair: lib a3c1e42f5b0ebda6 map ed7212a3189a4565 on both sides, Library Check PASSES; C6 9 of 9 equal", "source": "md5sum and read by W3"}, {"md5": "c3c70e91", "path": "ask579/w4/write/fetchback_eng_579.json", "note": "engine fetch-back after the write", "source": "md5sum by W3"}, {"md5": "b05b4478", "path": "ask579/w4/write/fetchback_child_579.json", "note": "child fetch-back after the write", "source": "md5sum by W3"}]$j$::jsonb,
  $j${"engine": {"path": "ask579/w4/write/revert_eng_579.json", "md5": "6bdb3d7a", "note": "the engine before ASK 579 (20db58ee), 423 nodes, made at the write"}, "child": {"path": "ask579/w4/write/revert_child_579.json", "md5": "2d0a38be", "note": "the child before ASK 579 (74353c40), 156 nodes, made at the write"}, "order": "NOT A WHOLE-FILE REVERT NOW: four engine writes followed ASK 579 (ASK 611 fix 2, 627, 628, 578), and ASK 578 removed the child's Shared Library node. A whole-file PUT of either revert file would also remove those. A revert of ASK 579 alone would restore the nine Extract nodes from revert_eng_579.json into the live engine and leave the library lines in place; that path is W3's reading and is not built or graded.", "database": "none: no database object was changed", "rehearsed": "no", "source": "md5sum and node counts by W3; Wall 11775; audit 41783, 41819, 41828, 41852"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "PASS (plan draft 1)", "wall_id": 11104, "md5_graded": "b1cba096", "verdict_norm": "PASS", "source": "Wall 11104; fairjudge/w1/g579/grade.md (commit 557ec2e0)"}, {"seat": "W1", "verdict": "PASS WITH N1 (plan rev 2)", "wall_id": 11739, "md5_graded": "922b1a04", "verdict_norm": "PASS", "source": "Wall 11739; fairjudge/w1/g579/grade_plan579_rev2.md 4d199c73 (commit cd27b44e)"}, {"seat": "W1", "verdict": "AGREE as the baseline for C6 (the replay of the live code on the 42071 inputs, 9 of 9; W1's own re-run byte-equal, with a negative control)", "wall_id": 11757, "md5_graded": "902b568b", "verdict_norm": "PASS", "source": "Wall 11757; fairjudge/w1/g579/check_c6_579.md (commit aef5cd2f)"}, {"seat": "W1", "verdict": "PASS WITH N1 (build re-cut, engine target; W1's rebuild byte-equal)", "wall_id": 11762, "md5_graded": "115b1db5", "verdict_norm": "PASS", "source": "Wall 11762; fairjudge/w1/g579/grade_build579_recut.md (commit 3c28422a)"}, {"seat": "W1", "verdict": "PASS WITH N1 (build re-cut, child target; the same grade)", "wall_id": 11762, "md5_graded": "fe01ca77", "verdict_norm": "PASS", "source": "Wall 11762; fairjudge/w1/g579/grade_build579_recut.md (commit 3c28422a)"}]$j$::jsonb,
  ARRAY['115b1db5', 'fe01ca77'], '[41763]'::jsonb,
  $j$[{"kind": "n8n workflow", "name": "ORACLE_DEBATE_V1 (engine)", "before": "20db58ee, 423 nodes", "after": "3afa1c1f-03ca-4297-8b7f-83ba8d6dd87c (17:43 CST), active, 423 nodes; changed: C4G, C3G, C1B, D2B, C2B, D3B, C3B, D4B and C4B Extract (each rebuilds its served text from the Shared Library through a loader; in the six try nodes the loader stands before the try) and Shared Library (270 lines and nine MAP entries added; no existing line moved or changed; library a3c1e42f5b0ebda6, 3,852 lines)"}, {"kind": "n8n workflow", "name": "child (second alternate pass)", "before": "74353c40, 156 nodes", "after": "cd97165c-5818-4a68-8987-45d4057c91e1, active, 156 nodes; Shared Library only (the same lines and MAP entries). ASK 578 has since removed that node (audit 41852)."}]$j$::jsonb,
  $j$[{"name": "t579.js on the base (live 20db58ee / 74353c40), 99 checks", "result": "ALL PASS by W4 and by W1's own run (byte-equal output and targets). Three nodes hold the __O423 statement and six the try block; the child holds neither shape outside its library; each node's rebuilt text is byte-equal to the text it held.", "source": "out_t579.txt ad55c232; Wall 11759, 11762"}, {"name": "C6: the nine Extract nodes run offline on the stored inputs of run 42071", "result": "9 of 9 outputs equal the stored outputs, for the live code (W4; W1's re-run byte-equal, and W1's control with two replies swapped gives 2 DIFFERENT, 7 EQUAL), for the target, and for the fetch-back at the write. A re-call ran in C2B and C3B Extract only, so a re-call through a try node is NOT SHOWN.", "source": "Wall 11756, 11757, 11762, 11775; out_c6_579_target.txt 902b568b"}, {"name": "Standing set and pair check", "result": "31 PASS, 0 FAIL on the targets and at the write, before and after (S4: engine 290 of 290 and child 67 of 67 expressions compile). Pair Library Check PASSES, lib a3c1e42f5b0ebda6, map ed7212a3189a4565.", "source": "write579_run.txt 5439cd0d; notes579.md; Wall 11762"}, {"name": "Whether C6 can be rebuilt from stored database rows", "result": "NO (W4): the nodes read raw replies and node outputs that no table stores; hence the limited read of execution 42071 on the operator's press.", "source": "Wall 11744, 11756"}]$j$::jsonb,
  $j$[{"seat": "W1", "result": "MATCH (live engine 3afa1c1f active, 423 nodes, parameters equal target 115b1db5 and connections equal; against 20db58ee exactly the nine Extract nodes and the Shared Library differ; child cd97165c active, 156 nodes, equal to target fe01ca77, only the Shared Library differs from 74353c40). Standing, pair and C6 were carried over from W1's re-cut grade of the same targets and not re-run on the fetch.", "wall_id": 11781, "source": "Wall 11781; fairjudge/w1/g579/readback579.md (commit 4d9ea200)"}]$j$::jsonb,
  $j${"case": "NO RUN YET since the write (debate_results last row 17:21 CST 2026-11-24, run 42373, which ran on engine 20db58ee before this write; read by W3 19:49 CST).", "runs": [], "mark_for_the_next_run": "no error text \"pkgX579\" in debate_errors, and the run's saved row and report exist. Two clean live runs are owed.", "not_shown": "a re-call through one of the six try nodes (C4G, C3G, C1B, D2B, D4B, C4B Extract): shown by no run and not by the C6 replay.", "source": "plan rev 2; notes579.md; Wall 11756, 11775"}$j$::jsonb,
  $j${"op_doc": "none", "engine_manual": "NOT WRITTEN. Draft confirmed by W1 for its card: manual1123/w3/a579/em_pairs_579_draft1.json 5114ec60, one pair, part 11.2 v312 to 9c844df7 (Wall 11860, 11867, 11874). A revision row records the write and the run evidence."}$j$::jsonb,
  'read back', $j$[11099, 11104, 11114, 11736, 11739, 11744, 11756, 11757, 11759, 11762, 11764, 11775, 11778, 11779, 11781]$j$::jsonb)
RETURNING id)
